<?php require __DIR__.'/includes/header.php';$p=dev_require_project($projectId);
$counts=[];$bs=db()->prepare('SELECT COUNT(*) FROM construction_buildings WHERE construction_project_id=? AND is_archived=0');$bs->execute([$projectId]);$counts['buildings']=(int)$bs->fetchColumn();$counts['master_progress']=dev_schedule_progress($projectId,null);foreach(['construction_daily_logs'=>'logs','construction_tasks'=>'tasks','construction_photos'=>'photos','construction_documents'=>'documents'] as $t=>$k){$s=db()->prepare("SELECT COUNT(*) FROM $t WHERE construction_project_id=?");$s->execute([$projectId]);$counts[$k]=(int)$s->fetchColumn();}$s=db()->prepare('SELECT COUNT(*) FROM construction_schedule_items WHERE construction_project_id=? AND is_inspection=1 AND status<>\'Complete\'');$s->execute([$projectId]);$counts['inspections']=(int)$s->fetchColumn();
$activity=db()->prepare('SELECT ca.*,au.full_name FROM construction_activity ca LEFT JOIN admin_users au ON au.id=ca.admin_user_id WHERE ca.construction_project_id=? ORDER BY ca.created_at DESC LIMIT 15');$activity->execute([$projectId]);
?>
<div class="page-head"><div><span class="badge"><?=e($p['status'])?></span><h1><?=e($p['project_name'])?></h1><p class="muted"><?=e(trim(($p['city']??'').', '.($p['state']??''),', '))?> · <?=e((string)($p['phase']??''))?></p></div><?php if(dev_is_super()):?><a class="btn btn-secondary" href="projects.php?edit=<?=$projectId?>">Edit Project</a><?php endif;?></div>
